const [showEditor,setShowEditor]=useState(false);const [editSrc,setEditSrc]=useState("");const [editTool,setEditTool]=useState<"crop"|"colour"|"draw"|"text">("crop");const [editFilter,setEditFilter]=useState("None");const [editCrop,setEditCrop]=useState("Full");const [drawColor,setDrawColor]=useState("#FF0000");const [drawSize,setDrawSize]=useState(6);const [editText,setEditText]=useState("");const [editTextColor,setEditTextColor]=useState("#FFFFFF");const [editTextSize,setEditTextSize]=useState(32);
const editCanvasRef=useRef<any>(null);const editBaseRef=useRef<any>(null);const editDrawRef=useRef<any[]>([]);const isDrawing=useRef(false);const lastDraw=useRef<any>(null);
function openEditor(src:string){setEditSrc(src);setEditFilter("None");setEditCrop("Full");setEditText("");setEditTool("crop");editDrawRef.current=[];setShowEditor(true);setShowAttach(false)}
useEffect(()=>{if(!showEditor||!editSrc)return;const img=new Image();img.onload=()=>{editBaseRef.current=img;const c=editCanvasRef.current;if(c){c.width=img.naturalWidth||img.width;c.height=img.naturalHeight||img.height;redrawEdit()}};img.src=editSrc},[showEditor,editSrc]);
function getF(f:string){if(f==="Warm")return "sepia(0.12) saturate(1.08) brightness(1.02)";if(f==="Cool")return "hue-rotate(8deg) saturate(1.05)";if(f==="Black & White")return "grayscale(1)";if(f==="Vivid")return "saturate(1.15) contrast(1.03)";if(f==="Soft")return "brightness(1.05) contrast(0.98) saturate(0.95)";if(f==="Natural")return "saturate(1.05) brightness(1.03)";return "none"}
function redrawEdit(){const c=editCanvasRef.current;const img=editBaseRef.current;if(!c||!img)return;const ctx=c.getContext("2d");ctx.clearRect(0,0,c.width,c.height);ctx.save();ctx.filter=getF(editFilter);ctx.drawImage(img,0,0,c.width,c.height);ctx.restore();editDrawRef.current.forEach((l:any)=>{ctx.strokeStyle=l.color;ctx.lineWidth=l.size;ctx.lineCap="round";ctx.beginPath();ctx.moveTo(l.from.x,l.from.y);ctx.lineTo(l.to.x,l.to.y);ctx.stroke()});if(editText){ctx.font="bold "+editTextSize+"px Arial";ctx.lineWidth=4;ctx.strokeStyle="rgba(0,0,0,0.8)";ctx.strokeText(editText,20,60);ctx.fillStyle=editTextColor;ctx.fillText(editText,20,60)}}
useEffect(()=>{if(showEditor)redrawEdit()},[editFilter,editText,editTextColor,editTextSize]);
function cPos(e:any){const r=editCanvasRef.current.getBoundingClientRect();const x=(e.touches?e.touches[0].clientX:e.clientX)-r.left;const y=(e.touches?e.touches[0].clientY:e.clientY)-r.top;return {x:x/r.width*editCanvasRef.current.width,y:y/r.height*editCanvasRef.current.height}}
function dStart(e:any){if(editTool!=="draw")return;isDrawing.current=true;lastDraw.current=cPos(e)}function dMove(e:any){if(!isDrawing.current||editTool!=="draw")return;const cur=cPos(e);const line={from:{...lastDraw.current},to:{...cur},color:drawColor,size:drawSize};editDrawRef.current.push(line);const ctx=editCanvasRef.current.getContext("2d");ctx.strokeStyle=drawColor;ctx.lineWidth=drawSize;ctx.lineCap="round";ctx.beginPath();ctx.moveTo(line.from.x,line.from.y);ctx.lineTo(line.to.x,line.to.y);ctx.stroke();lastDraw.current=cur}function dEnd(){isDrawing.current=false}
function sendEdited(){const c=editCanvasRef.current;if(!c)return;let finalC=c;if(editCrop!=="Full"){let sx=0,sy=0,sw=c.width,sh=c.height;if(editCrop==="Square"){const s=Math.min(sw,sh);sx=(sw-s)/2;sy=(sh-s)/2;sw=s;sh=s}if(editCrop==="16:9"){const th=sw*9/16;if(th<=sh){sy=(sh-th)/2;sh=th}else{const tw=sh*16/9;sx=(sw-tw)/2;sw=tw}}if(editCrop==="4:3"){const th=sw*3/4;if(th<=sh){sy=(sh-th)/2;sh=th}else{const tw=sh*4/3;sx=(sw-tw)/2;sw=tw}}const tmp=document.createElement("canvas");tmp.width=sw;tmp.height=sh;tmp.getContext("2d").drawImage(c,sx,sy,sw,sh,0,0,sw,sh);finalC=tmp}pushMsg({type:"photo",url:finalC.toDataURL("image/jpeg",0.92)});setShowEditor(false);setEditText("")}
// CAMERA - FILTERS / BEAUTY / TORCH / FLIP / VIDEO REC
const [showLiveCamera,setShowLiveCamera]=useState(false);const [cameraMode,setCameraMode]=useState<"photo"|"video">("photo");const [capturedPhoto,setCapturedPhoto]=useState("");const [isVideoRec,setIsVideoRec]=useState(false);const [recTimerSec,setRecTimerSec]=useState(0);const recTimerSecRef=useRef<any>(null);
const liveVideoRef=useRef<any>(null);const liveStreamRef=useRef<any>(null);const liveCanvasRef=useRef<any>(null);const videoRecRef=useRef<any>(null);const videoChunks=useRef<any[]>([]);
const [facingMode,setFacingMode]=useState<"user"|"environment">("user");const [torchOn,setTorchOn]=useState(false);const [showEffects,setShowEffects]=useState(false);const [effectTab,setEffectTab]=useState("Filters");const [filterEffect,setFilterEffect]=useState("None");const [beautyLevel,setBeautyLevel]=useState(0);const [isFlipping,setIsFlipping]=useState(false);
function getFilterStyle(filter:string,beauty:number){let f="";if(filter==="Warm")f="sepia(0.12) saturate(1.08) brightness(1.02)";if(filter==="Cool")f="hue-rotate(8deg) saturate(1.05)";if(filter==="Black & White")f="grayscale(1)";if(filter==="Vivid")f="saturate(1.15) contrast(1.03)";if(filter==="Soft")f="brightness(1.05) contrast(0.98) saturate(0.95)";if(filter==="Natural")f="saturate(1.05) brightness(1.03)";if(beauty>0){const b=beauty*0.012;if(f)f+=" ";f+="brightness("+(1+b).toFixed(3)+") contrast("+(1-beauty*0.008).toFixed(3)+") saturate("+(1+beauty*0.012).toFixed(3)+")"}return f||"none"}
async function openLiveCamera(){setShowAttach(false);setShowLiveCamera(true);setCapturedPhoto("");setCameraMode("photo");setFilterEffect("None");setBeautyLevel(0);setFacingMode("user");setTorchOn(false);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});liveStreamRef.current=stream;setTimeout(()=>{if(liveVideoRef.current){liveVideoRef.current.srcObject=stream;liveVideoRef.current.play()}},200)}catch(e){alert("Camera permission dein!");setShowLiveCamera(false)}}
async function flipCamera(){if(isFlipping)return;setIsFlipping(true);const nf=facingMode==="user"?"environment":"user";try{const old=liveStreamRef.current;if(old)old.getTracks().forEach((t:any)=>t.stop());setTorchOn(false);await new Promise(r=>setTimeout(r,350));let stream=null;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{exact:nf}},audio:true})}catch(e){stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:nf},audio:true})}setFacingMode(nf);liveStreamRef.current=stream;if(liveVideoRef.current){liveVideoRef.current.srcObject=stream;await liveVideoRef.current.play().catch(()=>{})}}catch(e){alert("Back Camera nahi khula!")}setIsFlipping(false)}
function closeLiveCamera(){setTorchOn(false);if(liveStreamRef.current){liveStreamRef.current.getTracks().forEach((t:any)=>t.stop());liveStreamRef.current=null}setShowLiveCamera(false);setCapturedPhoto("");setIsVideoRec(false);setShowEffects(false);if(recTimerSecRef.current)clearInterval(recTimerSecRef.current);setRecTimerSec(0)}
function capturePhoto(){if(!liveVideoRef.current)return;const v=liveVideoRef.current;const c=liveCanvasRef.current;if(!c)return;c.width=v.videoWidth;c.height=v.videoHeight;const ctx=c.getContext("2d");ctx.filter=getFilterStyle(filterEffect,beautyLevel);ctx.drawImage(v,0,0);openEditor(c.toDataURL("image/jpeg",0.9))}
function startVideoRec(){if(!liveStreamRef.current)return;videoChunks.current=[];const rec=new MediaRecorder(liveStreamRef.current);videoRecRef.current=rec;rec.ondataavailable=(e:any)=>{if(e.data.size>0)videoChunks.current.push(e.data)};rec.onstop=()=>{const blob=new Blob(videoChunks.current,{type:"video/webm"});const reader=new FileReader();reader.onloadend=()=>{pushMsg({type:"video",url:reader.result})};reader.readAsDataURL(blob);closeLiveCamera()};rec.start();setIsVideoRec(true);setRecTimerSec(0);if(recTimerSecRef.current)clearInterval(recTimerSecRef.current);recTimerSecRef.current=setInterval(()=>setRecTimerSec(t=>t+1),1000)}
function stopVideoRec(){if(videoRecRef.current&&isVideoRec){try{videoRecRef.current.stop()}catch(e){}setIsVideoRec(false)}if(recTimerSecRef.current)clearInterval(recTimerSecRef.current)}
async function toggleTorch(){const stream=liveStreamRef.current||streamRef.current;if(!stream){alert("Pehle Back Camera kholein!");return}const track=stream.getVideoTracks()[0];if(!track)return;if(facingMode==="user"){alert("Torch sirf Back Camera par! Pehle 🔄 dabao!");return}try{const caps:any=track.getCapabilities&&track.getCapabilities();if(caps&&!caps.torch){alert("Is phone me Torch nahi hai!");return}await track.applyConstraints({advanced:[{torch:!torchOn} as any]});setTorchOn(!torchOn)}catch(e){alert("Torch On nahi hui!")}}
// VOICE RECORDING
const [recording,setRecording]=useState(false);const [locked,setLocked]=useState(false);const [recTime,setRecTime]=useState(0);const [recHint,setRecHint]=useState("");const [playingIdx,setPlayingIdx]=useState<number|null>(null);const audioRef=useRef<any>(null);const [audioProgress,setAudioProgress]=useState(0);const recRef=useRef<any>(null);const recChunks=useRef<any[]>([]);const recTimer=useRef<any>(null);const startX=useRef(0);const startY=useRef(0);const isCancel=useRef(false);
function formatTime(sec:number){const m=Math.floor(sec/60);const ss=sec%60;return m+":"+(ss<10?"0"+ss:ss)}
async function startRecording(e:any){if(recording||locked)return;if(isBlocked)return;if(e){e.preventDefault();e.stopPropagation()}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream);recRef.current=rec;recChunks.current=[];rec.ondataavailable=(ev:any)=>{if(ev.data.size>0)recChunks.current.push(ev.data)};rec.start(250);setRecording(true);setRecTime(0);setRecHint("");if(recTimer.current)clearInterval(recTimer.current);recTimer.current=setInterval(()=>setRecTime(t=>t+1),1000)}catch(err){alert("Mic permission dein!");setRecording(false)}}
function onMicMove(e:any){if(!recording||locked)return;const t=e.touches?e.touches[0]:e;if(!t)return;const dx=t.clientX-startX.current;const dy=t.clientY-startY.current;if(dx<-60){isCancel.current=true;setRecHint("← Choro to Cancel")}else if(dy<-60){setRecHint("↑ Choro to Lock")}else{isCancel.current=false;setRecHint("")}}
function onMicRelease(e:any){if(!recording)return;if(e)e.preventDefault();const endX=e.changedTouches?e.changedTouches[0].clientX:e.clientX||0;const endY=e.changedTouches?e.changedTouches[0].clientY:e.clientY||0;const dx=endX-startX.current;const dy=endY-startY.current;if(dy<-60){setLocked(true);setRecHint("Locked - Send dabao");return}if(locked)return;if(isCancel.current||dx<-60){finishRecording(false)}else{finishRecording(true)}}
function finishRecording(sendIt:boolean){if(!recRef.current)return;if(recTimer.current)clearInterval(recTimer.current);const rec=recRef.current;const curTime=recTime;rec.onstop=()=>{try{if(rec.stream)rec.stream.getTracks().forEach((t:any)=>t.stop())}catch(e){}if(sendIt&&curTime>0&&recChunks.current.length){const blob=new Blob(recChunks.current,{type:"audio/webm"});const reader=new FileReader();reader.onloadend=()=>{pushMsg({type:"voice",url:reader.result,duration:formatTime(curTime)})};reader.readAsDataURL(blob)}};try{if(rec.state!=="inactive")rec.stop()}catch(e){}setRecording(false);setLocked(false);setRecHint("");isCancel.current=false;setRecTime(0)}
function toggleVoicePlay(idx:number,url:string){if(playingIdx===idx){if(audioRef.current)audioRef.current.pause();setPlayingIdx(null);return}if(audioRef.current)audioRef.current.pause();const a=new Audio(url);audioRef.current=a;a.ontimeupdate=()=>{if(a.duration)setAudioProgress((a.currentTime/a.duration)*100)};a.onended=()=>{setPlayingIdx(null);setAudioProgress(0)};a.play();setPlayingIdx(idx)}
