async function startCall(n:string,t:string){setS(n);setCallType(t);setCall(n);setCamOn(true);setMicOn(true);setCallParticipants([]);setShowAddToCall(false);setShowEffects(false);setCallFilter("None");setCallBeauty(0);setFacingMode("user");setTorchOn(false);setCallHistory((p)=>[{name:n,type:t,dir:"Outgoing",date:"Today",time:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}),duration:"00:00",missed:false},...p]);if(t==="Video"){try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});streamRef.current=stream;setTimeout(()=>{if(videoRef.current){videoRef.current.srcObject=stream;videoRef.current.play()}},200)}catch(e){alert("Camera permission dein!")}}}
function endCall(){setTorchOn(false);if(streamRef.current){streamRef.current.getTracks().forEach((tr:any)=>tr.stop());streamRef.current=null}setCall("");setCallParticipants([]);setShowAddToCall(false);setShowEffects(false)}
function toggleCam(){setCamOn(!camOn);if(streamRef.current)streamRef.current.getVideoTracks().forEach((tr:any)=>tr.enabled=!camOn)}function toggleMic(){setMicOn(!micOn);if(streamRef.current)streamRef.current.getAudioTracks().forEach((tr:any)=>tr.enabled=!micOn)}
function addPersonToCall(name:string){if(callParticipants.includes(name))return;if(callParticipants.length>=9){alert("Max 10 people!");return}setCallParticipants([...callParticipants,name]);setShowAddToCall(false)}
